[package]
name = "memory"
version = "0.1.0"
edition = "2021"

[lib]
crate-type = ["cdylib"]

[dependencies]
rand = "0.8"
lazy_static = "1.4"

use std::collections::HashMap;
use std::sync::Mutex;
use lazy_static::lazy_static;
use rand::Rng;
use std::slice;

lazy_static! {
    static ref MEMORY_STORE: Mutex<HashMap<u64, Vec<f64>>> = Mutex::new(HashMap::new());
    static ref NEXT_ID: Mutex<u64> = Mutex::new(1);
}

#[no_mangle]
pub extern "C" fn memory_insert(ptr: *const f64, len: usize) -> u64 {
    let input_vec: Vec<f64> = unsafe {
        assert!(!ptr.is_null());
        slice::from_raw_parts(ptr, len).to_vec()
    };

    let mut id_lock = NEXT_ID.lock().unwrap();
    let id = *id_lock;
    *id_lock += 1;
    drop(id_lock);

    let mut store_lock = MEMORY_STORE.lock().unwrap();
    store_lock.insert(id, input_vec);

    id
}

#[no_mangle]
pub extern "C" fn memory_query_nearest(ptr: *const f64, len: usize) -> u64 {
    let input_vec: Vec<f64> = unsafe {
        assert!(!ptr.is_null());
        slice::from_raw_parts(ptr, len).to_vec()
    };

    let store_lock = MEMORY_STORE.lock().unwrap();
    let mut best_id = 0;
    let mut max_similarity = -1.0;

    for (id, vec) in store_lock.iter() {
        if vec.len() != input_vec.len() {
            continue;
        }

        let dot_product: f64 = vec.iter().zip(input_vec.iter()).map(|(a, b)| a * b).sum();
        let magnitude_a: f64 = vec.iter().map(|x| x * x).sum::<f64>().sqrt();
        let magnitude_b: f64 = input_vec.iter().map(|x| x * x).sum::<f64>().sqrt();

        let cosine_sim = if magnitude_a > 0.0 && magnitude_b > 0.0 {
            dot_product / (magnitude_a * magnitude_b)
        } else {
            0.0
        };

        if cosine_sim > max_similarity {
            max_similarity = cosine_sim;
            best_id = *id;
        }
    }

    best_id
}

#[no_mangle]
pub extern "C" fn memory_exists(id: u64) -> bool {
    let store_lock = MEMORY_STORE.lock().unwrap();
    store_lock.contains_key(&id)
}

type NeuralState:
  Active { energy: f24 }
  Resting { recovery: f24 }

type Synapse:
  Connection { weight: f24, target: NeuralState }
  Terminal

def activation_function(x):
  return (x / (1.0 + (x * x).sqrt()))

def process_signal(synapse, input_signal):
  match synapse:
    case Synapse/Connection:
      match synapse.target:
        case NeuralState/Active:
          return activation_function(input_signal * synapse.weight * synapse.target.energy) + process_signal(synapse.target, input_signal)
        case NeuralState/Resting:
          return 0.0
    case Synapse/Terminal:
      return 0.0

def build_network(depth, seed):
  if depth == 0:
    return Synapse/Terminal
  else:
    return Synapse/Connection { 
      weight: seed, 
      target: NeuralState/Active { energy: 1.0 } 
    }

def main:
  network = build_network(100, 0.5)
  result = process_signal(network, 1.0)
  return result

import std/os/process
import std/core/console
import std/num/float64

extern fun c_memory_insert( ptr : c-pointer, len : int64 ) : int64
  c "memory_insert"

extern fun c_memory_query( ptr : c-pointer, len : int64 ) : int64
  c "memory_query_nearest"

effect agi_memory {
  ctl store_vector( v : vector<float64> ) : int64
  ctl find_similar( v : vector<float64> ) : int64
}

effect agi_compute {
  ctl run_cortex_cycle() : float64
}

fun serialize_vector( v : vector<float64> ) : (c-pointer, int64) {
  val len = v.length
  val buf = v.c-float64-array
  (buf, len.int64)
}

fun cortex_loop( cycles : int ) : agi_memory () {
  if cycles == 0 then () else {
    val input = vector(128, fn(i){ 0.5 })
    val id = store_vector(input)
    val match_id = find_similar(input)

    if id == match_id then {
      println("CONVERGENCE_ACHIEVED_AT_ID: " ++ id.show)
    } else {
      println("DIVERGENCE_DETECTED")
    }
    cortex_loop(cycles - 1)
  }
}

pub fun main() {
  with handler {
    ctl store_vector(v) {
      unsafe {
        val (ptr, len) = serialize_vector(v)
        resume(c_memory_insert(ptr, len))
      }
    }
    ctl find_similar(v) {
      unsafe {
        val (ptr, len) = serialize_vector(v)
        resume(c_memory_query(ptr, len))
      }
    }
  }

  cortex_loop(10)
}

